import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;

public class BandejaAlertas implements Iterable<Alerta> {
    private ArrayList<Alerta> pendientes;


    // Constructor vacio
    public BandejaAlertas() {
        pendientes = new ArrayList<Alerta>();
    }


    // Agregar alerta, recibe la Alerta, la agrega
    public boolean agregarAlerta(Alerta alerta) {

        if (alerta == null) {
            return false;
        }

        if (alerta.getAtendida()) {
            return false;
        }

        // Evita registrar dos veces la misma alerta
        for (Alerta pendiente : pendientes) {
            if (pendiente.getCodigo() == alerta.getCodigo()) {
                return false;
            }
        }

        pendientes.add(alerta);
        return true;
    }


    // Siguiente alerta
    public Alerta siguienteAlerta() {

        if (pendientes.isEmpty()) {
            return null;
        }

        // Ordena una copia para no modificar la lista original y preservarla
        ArrayList<Alerta> ordenadas = new ArrayList<Alerta>(pendientes);
        Collections.sort(ordenadas);

        return ordenadas.get(0);
    }


    // Retirar siguiente. Ordenar y calcular será tarea de una nueva Clase más adelante
    public Alerta retirarSiguiente() {

        Alerta alerta = siguienteAlerta();

        if (alerta == null) {
            return null;
        }

        pendientes.remove(alerta);
        return alerta;
    }


    // Iterator
    // Implementa el metodo de Iterable (for each)

    @Override
    public Iterator<Alerta> iterator() {

        ArrayList<Alerta> ordenadas = new ArrayList<Alerta>(pendientes);
        Collections.sort(ordenadas);

        return ordenadas.iterator();
    }
}
